import { Request, Response } from "express";
import { body, param } from "express-validator";
import { ApiResponse, routeParam } from "@tabletennisshop/common";
import { InventoryService } from "../service/inventory.service";

export const subtractQuantityController =  [
    param("id").isMongoId().withMessage("Invalid product ID"),
    body("quantity").isInt({min:1}).withMessage("Invalid quantity"),
    async (req: Request, res: Response)=>{
        const product_id = routeParam(req, "id");
        const { quantity } = req.body;

        const result = await InventoryService.subtractQuantityByProductId({ product_id, quantity });

        const response: ApiResponse = {
            statusCode: 200, 
            data: result,
            success: true
        }
        res.status(200).json(response);
    },
]